  [20049] = { "Aumenta del $N1% i danni fisici e da sacro che infliggi per $D1 dopo aver messo a segno un colpo critico non periodico. Si accumula fino a $N3 volte.", nil, 0xa8809935, nil, "um" },
  [20060] = { "Aumenta la probabilità di parata del $N1%.", nil, 0x8ac819e9, nil, "um" },
  [20066] = { "Pone il bersaglio nemico in uno stato di meditazione, rendendolo inabilitato per un massimo di $D1. Eventuali danni inflitti risvegliano il bersaglio. Funziona solo sugli umanoidi.", "Inabilitato.", 0x9e894272, 0x147cb83f, "uu" },
