  [20101] = { "Riduce del $N1% il costo in mana di tutti gli incantesimi e le abilità a lancio istantaneo.", nil, 0xe3cdca90, nil, "um" },
  [20111] = { "Aumenta del $N1% i danni inflitti con le armi da mischia a due mani.", nil, 0xd2cc2ad8, nil, "um" },
  [20116] = { "Consacra il terreno sotto il Paladino, infliggendo $N1 danni da sacro in $D1 ai nemici che entrano nell'area. I primi $N3 nemici che entrano nell'area subiscono altri $N4 danni in $D2.", "$N1 danni ogni $N2 secondi.", 0x975a5486, 0x6e147642, "uu" },
  [20117] = { "Aumenta del $N1% la probabilità di infliggere un colpo critico con gli attacchi in mischia.", nil, 0x1f5cd05b, nil, "um" },
  [20127] = { "Gli attacchi in mischia che ti infliggono danni hanno una probabilità del $N1% di aumentare la tua probabilità di blocco del $N2%. Dura $D1 o $N4 blocchi.", nil, 0x79f79fde, nil, "um" },
  [20138] = { "Aumenta del $N1% il bonus all'Armatura di ⟦Devotion Aura=Aura di Devozione⟧ e del $N2% tutte le cure ricevute dai membri del gruppo influenzati dalle tue Aure.", nil, 0x09506b57, nil, "um" },
  [20143] = { "Aumenta del $N1% il valore di Armatura fornito dai tuoi oggetti.", nil, 0x7e505d7e, nil, "um" },
  [20148] = { "Aumenta del $N1% i danni assorbiti dal tuo scudo.", nil, 0x34e968db, nil, "um" },
  [20149] = { "Aumenta del $N1% i danni assorbiti dal tuo scudo.", nil, 0x34e968db, nil, "um" },
  [20150] = { "Aumenta del $N1% i danni assorbiti dal tuo scudo e dà ai tuoi blocchi una probabilità del $N2% di rigenerare il $N3% del tuo mana massimo. Può verificarsi solo una volta ogni $N4 s.", nil, 0x0c6407c7, nil, "um" },
  [20154] = { "Infonde nel Paladino lo spirito sacro per $D1, facendo infliggere a ogni attacco in mischia $N2 danni da sacro aggiuntivi. Le armi più lente infliggono più danni da sacro per colpo. Sul Paladino può essere attivo un solo Sigillo alla volta.", "Gli attacchi in mischia infliggono $N1 danni da sacro aggiuntivi.", 0x552c40c3, 0x8d406bfa, "uu" },
  [20162] = { "Infonde nel Paladino lo spirito di un crociato per $D1, fornendo $N2 potenza d'attacco in mischia. Il Paladino attacca inoltre più velocemente del $N3%, ma infligge meno danni con ogni attacco. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D2, aumentando fino a $N5 i danni da sacro che subisce. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Potenza d'attacco in mischia aumentata di $N1. Gli attacchi in mischia sono più veloci del $N2%, ma infliggono meno danni.", 0x2b89e2f7, 0xf3c132e9, "uu" },
  [20163] = { "Infonde nel Paladino la furia divina per $D1, facendo infliggere agli attacchi in mischia $N2 danni da sacro aggiuntivi. Con uno scudo equipaggiato, ogni attacco fornisce anche uno scudo assorbente pari al $N3% dei danni da sacro inflitti. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo infligge $N4 danni da sacro a un nemico e lo provoca, inducendolo ad attaccarti per $D2.", "Gli attacchi in mischia infliggono $N1 danni da sacro aggiuntivi.", 0x9758716b, 0x02f49abe, "uu" },
  [20164] = { "Infonde nel Paladino lo spirito della giustizia per $D1, dando a ogni attacco in mischia una probabilità di stordire per $D2. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D3, impedendogli di fuggire. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Gli attacchi in mischia hanno una probabilità di stordire per $D1.", 0x297d1926, 0x0e961291, "uu" },
  [20165] = { "Infonde nel Paladino la luce divina per $D1, dando a ogni attacco in mischia una probabilità di curare il Paladino di $N2. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D2, dando agli attacchi in mischia contro il nemico giudicato una probabilità di curare l'attaccante di $N4. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Gli attacchi in mischia hanno una probabilità di curarti di $N1.", 0x4ee2853b, 0x73c9462e, "uu" },
  [20166] = { "Infonde nel Paladino la saggezza divina per $D1, dando a ogni attacco in mischia una probabilità di rigenerare $N2 mana al Paladino. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D2, dando agli attacchi e agli incantesimi usati contro il nemico giudicato una probabilità di rigenerare $N4 mana all'attaccante. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Gli attacchi in mischia hanno una probabilità di rigenerare $N1 mana.", 0x0f831d16, 0x6adcff26, "uu" },
  [20170] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [20174] = { "Riduce di $D1 il tempo di recupero di ⟦Blessing of Protection=Benedizione della Protezione⟧ e aumenta di $D2 la durata di ⟦Blessing of Freedom=Benedizione della Libertà⟧.", nil, 0x876e8544, nil, "um" },
  [20177] = { "Fornisce una probabilità del $N1% dopo un blocco e del $N2% dopo aver subito un colpo critico non periodico di ottenere un attacco aggiuntivo. Accumula fino a $N3 attacchi aggiuntivi. Non può verificarsi a seguito di un blocco più di una volta ogni $D1.", nil, 0x61baa0e2, nil, "um" },
  [20183] = { "Sottopone il bersaglio al Giudizio, infliggendo danni da sacro.", nil, 0x2d426ec2, nil, "um" },
  [20184] = { "Impedisce al bersaglio di fuggire.", "Impossibile fuggire.", 0x4f595acb, 0xd1ba63cd, "uu" },
  [20185] = { "Gli attacchi in mischia effettuati contro di te hanno una probabilità di curare l'attaccante di $N1.", "Gli attacchi in mischia effettuati contro di te hanno una probabilità di curare l'attaccante di $N1.", 0xd9a93df2, 0xd9a93df2, "uu" },
  [20186] = { "Gli attacchi e gli incantesimi usati contro il bersaglio hanno una probabilità di rigenerare $N1 mana all'attaccante.", "Gli attacchi e gli incantesimi usati contro di te hanno una probabilità di rigenerare $N1 mana all'attaccante.", 0x9d1743a7, 0x02d810c9, "uu" },
  [20188] = { "Aumenta fino a $N1 i danni da sacro subiti.", "Danni da sacro subiti aumentati fino a un massimo di $N1.", 0x6174ebc2, 0x6174ebc2, "uu" },
