  [20194] = { "Aumenta di $D1 la durata di Blessing of Salvation.", nil, 0xb281ba8b, nil, "um" },
  [20195] = { "Aumenta di $D1 la durata di Blessing of Salvation.", nil, 0xb281ba8b, nil, "um" },
  [20196] = { "Aumenta del $N1% i danni che infliggi con le armi da mischia a una mano.", nil, 0xc1539303, nil, "um" },
  [20203] = { "Infligge danni da fuoco ai nemici vicini.", nil, 0x209abb75, nil, "um" },
  [20205] = { "Fornisce a ⟦Flash of Light=Lampo di Luce⟧, ⟦Holy Light=Luce Sacra⟧ e Light's Vigil una probabilità del $N1% di non perdere tempo di lancio quando subisci danni.", nil, 0xbd8bc43a, nil, "um" },
  [20210] = { "Dopo aver ottenuto un effetto critico con ⟦Flash of Light=Lampo di Luce⟧, ⟦Holy Light=Luce Sacra⟧, Light's Vigil o con la cura di ⟦Holy Shock=Folgore Sacra⟧, hai una probabilità del $N1% di ottenere mana pari al $N2% del costo base dell'incantesimo.", nil, 0x0add8f9c, nil, "um" },
  [20216] = { "Una volta attivato, fornisce al successivo ⟦Flash of Light=Lampo di Luce⟧, ⟦Holy Light=Luce Sacra⟧ o ⟦Holy Shock=Folgore Sacra⟧ una probabilità di effetto critico del $N1%.", "Probabilità di effetto critico del prossimo incantesimo ⟦Flash of Light=Lampo di Luce⟧, ⟦Holy Light=Luce Sacra⟧ o ⟦Holy Shock=Folgore Sacra⟧ aumentata del $N1%.", 0x42ed97be, 0x1e5cc109, "uu" },
  [20217] = { "Piazza una Benedizione sul bersaglio alleato, aumentando tutte le caratteristiche del $N1% per $D1. Il bersaglio alleato può ricevere solo una Benedizione per Paladino alla volta.", "Caratteristiche aumentate del $N1%.", 0xf4a4668d, 0xb6c88837, "uu" },
  [20218] = { "Aumenta del $N2% i danni da sacro inflitti dai membri del gruppo entro $N1 m. Il bersaglio alleato può ricevere solo un'Aura per Paladino alla volta.", "Danni da sacro inflitti aumentati del $N1%.", 0x50a2e842, 0xd68c8458, "uu" },
