  [20224] = { "Aumenta del $N1% i danni inflitti dai tuoi Sigilli e Giudizi.", nil, 0x60f953d9, nil, "um" },
  [20228] = { "Infligge $N1 danni da fuoco a un nemico e brucia il bersaglio, infliggendo $N2 danni aggiuntivi ogni $N3 s per $D2.", "$N1 danni da fuoco inflitti ogni $N2 s.", 0x8655b1c7, 0xbc8b8357, "uu" },
  [20229] = { "Infligge $N1 danni da fuoco ai nemici vicini e riduce la loro velocità di movimento del $N2% per $D1.", "Velocità di movimento ridotta del $N1%.", 0x24d9bd86, 0x08fe79f0, "uu" },
  [20230] = { "Contrattacca all'istante qualsiasi nemico che ti colpisce in mischia per $D1. Gli attacchi in mischia da dietro non possono essere contrattaccati. Al massimo $N2 attacchi provocano un contrattacco.", "Contrattacca tutti gli attacchi in mischia.", 0x7dde06c6, 0xff7e2588, "uu" },
