  [20254] = { "Aumenta l'effetto della tua Aura di Concentrazione di un ulteriore $N1%; inoltre la tua Aura di Concentrazione riduce del $N2% la durata degli effetti di silenzio e di interruzione sui membri del tuo gruppo.", nil, 0x80ce6c27, nil, "um" },
