  [20277] = { "Stordisce i nemici vicini, impedendo loro di muoversi o attaccare per $D1.", "Stordito.", 0x3546cc6b, 0x27f95286, "uu" },
  [20279] = { "Evoca un personaggio nemico.", nil, 0x9d2b0ae0, nil, "um" },
