  [20347] = { "Pervade il Paladino di luce divina per $D1, conferendo a ogni attacco in mischia una probabilità di curare il Paladino di $N2. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D2, conferendo agli attacchi in mischia contro il nemico giudicato una probabilità di curare l'attaccante di $N4. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Gli attacchi in mischia hanno una probabilità di curarti di $N1.", 0xfdc3929f, 0x359f840f, "uu" },
  [20348] = { "Pervade il Paladino di luce divina per $D1, conferendo a ogni attacco in mischia una probabilità di curare il Paladino di $N2. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D2, conferendo agli attacchi in mischia contro il nemico giudicato una probabilità di curare l'attaccante di $N4. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Gli attacchi in mischia hanno una probabilità di curarti di $N1.", 0xec4f65da, 0x35c1d1aa, "uu" },
  [20349] = { "Pervade il Paladino di luce divina per $D1, conferendo a ogni attacco in mischia una probabilità di curare il Paladino di $N2. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D2, conferendo agli attacchi in mischia contro il nemico giudicato una probabilità di curare l'attaccante di $N4. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Gli attacchi in mischia hanno una probabilità di curarti di $N1.", 0x21307699, 0x46c6518f, "uu" },
