  [20706] = { "Genera uno scudo attorno al bersaglio e lo protegge assorbendo $N1 danni. Dura $D1. Mentre lo scudo è attivo, il lancio d'incantesimi non viene interrotto dai danni subiti. Il bersaglio non può essere nuovamente protetto per $D2.", "Danni subiti assorbiti.", 0xebe6821c, 0x960eff1a, "uu" },
